/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Types: CatalogReviewEvidenceMember, CatalogReviewEvidenceImport
 *   Functions: catalogReviewImportEvidenceOf, catalogReviewImportEvidenceFilter,
 *              readCatalogReviewImportEvidence
 * Internal
 *   Functions: isRecord, list, appliedRelease, shared
 * @end-catalog */

/**
 * The import evidence an existing-Album review captures when it is first admitted to metadata lookup (adminCatalogReviewCapture.ts):
 * when every member of the Album is a Track a completed import published, not as a reused member, and still holds exactly the file
 * that import staged (publishedImportMedia, the byte checks local MP3 conversion makes, for any import actor and any audio type),
 * the MusicBrainz release every such import applied and the identifiers every member's staged file carries in its tags with one
 * value. Read once in the capture's transaction through the publication index; later changes to the imports or their lookup
 * records never reach a captured review. Private review evidence: never projected, never given to Luna. This module never imports
 * the review service.
 */
import type { ClientSession, ObjectId } from 'mongodb';
import { ADMIN_IMPORT_LIMITS as LIMITS, uuid, type ImportTagsView } from '../import/adminImportContract';
import { publishedImportMedia } from '../import/adminImportPublishedMedia';
import { importCollection, importLookupRecords, importPurposeFilter } from '../import/adminImportService';
import { importTagsV2View } from '../import/adminImportTags';
import { lookupCandidateSource, METADATA_LOOKUP_LIMITS } from '../lookup/lookupContract';
import { lookupTermProblem, normalizeGtin, normalizeMusicBrainzId } from '../lookup/lookupIdentifiers';
import type { CatalogReviewImportEvidence } from './adminCatalogReviewContract';

/** One member of the Album in source order: its manifest slot, its Track ID and the Track as the review's source check read it. */
export type CatalogReviewEvidenceMember = { slotId: string; trackId: string; track: unknown };
/** One import that may have published members: its stored publication and assets, and its lookup record's application (or null). */
export type CatalogReviewEvidenceImport = { publication: unknown; assets: unknown; applied: unknown };

const isRecord = (value: unknown): value is Record<string, any> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
const list = (value: unknown): unknown[] => Array.isArray(value) ? value : [];

/** The MusicBrainz release an import's lookup application applied: a preselected or chosen MusicBrainz candidate's release ID, else null. */
function appliedRelease(applied: unknown): string | null {
    if (!isRecord(applied) || (applied.choice !== 'preselected' && applied.choice !== 'chosen') || applied.source === 'itunes'
        || lookupCandidateSource(applied.candidateKey) !== 'musicbrainz') return null;
    return normalizeMusicBrainzId(applied.releaseId);
}
/** The one value every entry carries (exact string equality), or null when one lacks it or two disagree. */
function shared(values: readonly (string | null)[]): string | null {
    return values.length > 0 && values.every(value => value !== null && value === values[0]) ? values[0] : null;
}

/**
 * The evidence `imports` give for the members of Album `albumId`, or null. Each member must be published, with `reused` stored as
 * false, by exactly one import whose publication is complete for that Album, and its asset for that slot (`ready` or `deleted`)
 * must prove the Track's media (publishedImportMedia); otherwise, and for an Album without members, there is no evidence. The
 * applied release counts only when every contributing import applied the same MusicBrainz release (never an iTunes-only one);
 * each tag identifier only when every member's version-2 tags carry it with one valid value, so a gap or disagreement drops only
 * that identifier. Evidence without any identifier is null. Pure and total on malformed stored shapes.
 */
export function catalogReviewImportEvidenceOf(albumId: string, members: readonly CatalogReviewEvidenceMember[], imports: readonly CatalogReviewEvidenceImport[]): CatalogReviewImportEvidence | null {
    if (!members.length) return null;
    const contributing = new Set<CatalogReviewEvidenceImport>(), tags: (ImportTagsView | null)[] = [];
    for (const member of members) {
        const claims = imports.flatMap(item => {
            const publication = item.publication;
            if (!isRecord(publication) || publication.state !== 'complete' || publication.albumId !== albumId) return [];
            const entry = list(publication.tracks).find(track => isRecord(track) && track.id === member.trackId && track.reused === false && uuid(track.slotId));
            return isRecord(entry) ? [{ item, slotId: entry.slotId as string }] : [];
        });
        if (claims.length !== 1) return null;
        const [{ item, slotId }] = claims;
        const asset = list(item.assets).find(value => isRecord(value) && value.slotId === slotId && (value.state === 'ready' || value.state === 'deleted'));
        if (!publishedImportMedia(member.trackId, asset, member.track)) return null;
        contributing.add(item);
        const view = importTagsV2View((asset as Record<string, unknown>).tags);
        tags.push(view?.version === 2 ? view : null);
    }
    const releases = [...contributing].map(item => appliedRelease(item.applied));
    const pick = (read: (view: ImportTagsView) => string | null) => shared(tags.map(view => view ? read(view) : null));
    const catalogNumber = pick(view => view.identifiers.catalogNumber);
    const evidence: CatalogReviewImportEvidence = {
        releaseId: shared(releases),
        tagReleaseId: normalizeMusicBrainzId(pick(view => view.identifiers.musicBrainzReleaseId)),
        barcode: normalizeGtin(pick(view => view.identifiers.barcode))?.digits ?? null,
        catalogNumber: catalogNumber !== null && lookupTermProblem(catalogNumber, METADATA_LOOKUP_LIMITS.termLength) === null ? catalogNumber : null
    };
    return Object.values(evidence).some(value => value !== null) ? evidence : null;
}

/**
 * The filter that finds the completed imports that published any of `trackIds` as new members of Album `albumId`. The Album ID
 * term repeats the `$type` of the `admin_import_published_album` partial filter, since MongoDB uses a partial index only for a
 * query that implies its filter and an equality alone does not.
 */
export function catalogReviewImportEvidenceFilter(albumId: string, trackIds: readonly string[]) {
    return { ...importPurposeFilter, 'media.publication.albumId': { $eq: albumId, $type: 'string' as const }, 'media.publication.state': 'complete',
        'media.publication.tracks': { $elemMatch: { id: { $in: [...trackIds] }, reused: false } } };
}

/**
 * Reads, in the capture's transaction, the completed imports that published members of Album `albumId` (one bounded read through
 * the `admin_import_published_album` index; existing-Album reviews never match) and only the application of their lookup records,
 * then derives the evidence (catalogReviewImportEvidenceOf). No read for an Album without members; null when more imports match than
 * an Album can have members, since each Track is published once.
 */
export async function readCatalogReviewImportEvidence(albumId: string, members: readonly CatalogReviewEvidenceMember[], session: ClientSession): Promise<CatalogReviewImportEvidence | null> {
    if (!members.length) return null;
    const docs = await importCollection().find(catalogReviewImportEvidenceFilter(albumId, members.map(member => member.trackId)), { session,
        projection: { 'media.publication.albumId': 1, 'media.publication.state': 1, 'media.publication.tracks': 1, 'media.assets.slotId': 1, 'media.assets.state': 1,
            'media.assets.sha256': 1, 'media.assets.byteLength': 1, 'media.assets.tags': 1 } }).limit(LIMITS.files + 1).maxTimeMS(3_000).toArray();
    if (!docs.length || docs.length > LIMITS.files) return null;
    const lookups = await importLookupRecords(docs.map(doc => doc._id as ObjectId), session,
        { 'applied.releaseId': 1, 'applied.candidateKey': 1, 'applied.choice': 1, 'applied.source': 1 });
    return catalogReviewImportEvidenceOf(albumId, members, docs.map(doc => ({ publication: doc.media?.publication, assets: doc.media?.assets,
        applied: lookups.get(doc._id.toHexString())?.applied ?? null })));
}
